/* Business-facing portfolio layers. Forms remain explicit local previews. */
installMikhaPortfolio();
if(state.portfolioPro&&!state.portfolioPro.coverReview){const nice=state.projects.find(p=>p.id==='mikha-nice');if(nice?.cover==='assets/work/nice-1.webp')nice.cover='assets/work/nice-4.webp';state.portfolioPro.coverReview=true;save()}
let proView=null,proFilter='All',proSlide=0,stopProMotion=()=>{};
const proData=()=>state.portfolioPro||mikhaBusinessDefaults;
const proLabel=(n,text)=>`<div class="chapter-head"><span class="micro-label">${n} — ${text}</span><span aria-hidden="true">↗</span></div>`;
const proEdit=(key,index='')=>`data-pro-edit="${key}" data-pro-index="${index}"`;
const proButton=(text,action,extra='')=>`<button class="pro-link" data-action="${action}" ${extra}>${text}<span aria-hidden="true">↗</span></button>`;
function proProjects(){return state.projects.filter(p=>!['Hidden','Archived'].includes(p.status)&&p.featured)}
function proCards(projects){return projects.map((p,i)=>`<button class="story-project pro-reveal" data-action="preview-project:${esc(p.id)}" data-pro-project="${esc(p.id)}"><div class="story-project-image"><img src="${esc(p.cover)}" alt="${esc(p.title)}" loading="lazy" decoding="async"><span class="project-open">Explore the story ↗</span><span class="project-index">${String(i+1).padStart(2,'0')}</span></div><div class="story-project-caption"><h3>${esc(p.title)}</h3><span>${esc(p.category||p.type)}<br>${esc(p.year)}</span><span class="project-circle">↗</span></div>${p.notes?`<p class="pro-project-description">${esc(p.notes)}</p>`:''}</button>`).join('')}
function proServices(s,edit){return `<section class="pro-services pro-section" data-chapter="services" data-pro-section="${s.id}">${proLabel('02','WHAT WE CAN CREATE')}<div class="pro-heading pro-reveal"><h2>Good ideas.<br><i>Distinctive outcomes.</i></h2><p>From the identity at the heart of your brand to the campaigns that take it into the world.</p></div><div class="pro-service-list">${proData().services.map((item,i)=>`<div class="pro-service-row pro-reveal"><span class="pro-number">0${i+1}</span><div ${proEdit('services',i)}><span class="micro-label">${esc(item.line)}</span><h3>${esc(item.title)}</h3><p>${esc(item.description)}</p><div class="pro-tags">${item.deliverables.split('\n').slice(0,3).map(t=>`<span>${esc(t)}</span>`).join('')}</div>${proButton('Explore service','pro-service:'+item.id)}</div><button class="pro-service-image" data-action="pro-service:${item.id}" ${proEdit('services',i)} aria-label="Explore ${esc(item.title)}"><img src="${esc(item.image)}" alt="${esc(item.title)} — selected work" loading="lazy"></button></div>`).join('')}</div></section>`}
function proJourney(s){return `<section class="pro-journey pro-section" data-chapter="journey">${proLabel('05','THE EXPERIENCE BEHIND THE WORK')}<div class="pro-heading pro-reveal"><h2>Independent spirit.<br><i>Shared experience.</i></h2><p>A career across agency work, visual communication and design education.</p></div><div class="pro-timeline">${proData().journey.map((j,i)=>`<div class="pro-timeline-row pro-reveal" ${proEdit('journey',i)}><span class="pro-number">0${i+1}</span><div><h3>${esc(j.title)}</h3><p>${esc(j.company)} <span>· ${esc(j.location)}</span></p></div><p>${esc(j.detail)}</p></div>`).join('')}</div><a class="pro-link" href="${mikhaWorkSources.behance}" target="_blank" rel="noopener noreferrer">More on Behance <span>↗</span></a></section>`}
function proTestimonials(){const items=proData().testimonials;proSlide=Math.min(proSlide,items.length-1);return `<section class="pro-testimonials pro-section" data-chapter="testimonials" aria-roledescription="carousel" aria-label="Client perspectives">${proLabel('06','THE PEOPLE SIDE')}<div class="pro-quote-header"><h2>Good work starts<br>with <i>good chemistry.</i></h2><span class="pro-sample">SAMPLE TESTIMONIALS · FICTIONAL PEOPLE & BRANDS</span></div><div class="pro-slides">${items.map((t,i)=>`<figure class="pro-quote ${i===proSlide?'is-active':''}" ${i===proSlide?'':'hidden'} data-pro-slide="${i}" role="group" aria-roledescription="slide" aria-label="${i+1} of ${items.length}" ${proEdit('testimonials',i)}><span class="pro-quote-mark" aria-hidden="true">“</span><blockquote>${esc(t.quote)}</blockquote><figcaption><div class="pro-avatar" aria-hidden="true">${esc(t.name.split(' ').map(n=>n[0]).join(''))}</div><div><strong>${esc(t.name)}</strong><span>${esc(t.role)}</span></div><img class="pro-demo-logo" src="${esc(t.logo)}" alt="Fictional brand wordmark"></figcaption></figure>`).join('')}</div><div class="pro-slider-controls"><span class="pro-slide-count" aria-live="polite">${String(proSlide+1).padStart(2,'0')} / ${String(items.length).padStart(2,'0')}</span><div class="pro-dots">${items.map((_,i)=>`<button data-pro-control="slide" data-index="${i}" aria-label="Show testimonial ${i+1}" aria-pressed="${i===proSlide}"></button>`).join('')}</div><button data-pro-control="previous" aria-label="Previous testimonial">←</button><button data-pro-control="next" aria-label="Next testimonial">→</button><button class="pro-slider-play" data-pro-control="play" aria-pressed="false">Play</button></div></section>`}
function proInsights(){return `<section class="pro-insights pro-section" data-chapter="insights">${proLabel('07','NOTES FROM THE STUDIO')}<div class="pro-heading pro-reveal"><h2>A little <i>perspective.</i></h2><p>Thoughts on identity, campaigns and the craft behind them.<br><span class="pro-sample">SAMPLE EDITORIAL DRAFTS</span></p></div><div class="pro-insight-grid">${proData().insights.map((item,i)=>`<article class="pro-insight pro-reveal" ${proEdit('insights',i)}><button data-action="pro-article:${i}" aria-label="Read ${esc(item.title)}"><img src="${esc(item.image)}" alt="" loading="lazy"><span class="micro-label">${esc(item.category)} · 2 MIN READ</span><h3>${esc(item.title)}</h3><span class="pro-link">Read the note <span>↗</span></span></button></article>`).join('')}</div></section>`}
function proMentoring(){const m=proData().mentoring;return `<section class="pro-mentoring pro-section pro-reveal" data-chapter="mentoring"><div ${proEdit('mentoring')}><span class="micro-label">FOR DESIGNERS · SAMPLE OFFER</span><h2>${esc(m.title)}</h2><p>${esc(m.description)}</p></div><div class="pro-mentoring-aside"><span>${esc(m.duration)} / 1:1</span>${proButton('Discuss a portfolio review','pro-brief:Portfolio review')}<small>Preview offer. Availability and pricing to be confirmed.</small></div></section>`}
function proBriefForm(){return `<form class="pro-brief" data-pro-control="form"><div class="pro-form-head"><span class="micro-label">TELL ME WHAT YOU HAVE IN MIND</span><span class="pro-sample">LOCAL PREVIEW</span></div><div class="pro-form-grid"><label>Your name<input name="name" autocomplete="name" required placeholder="Alex Taylor"></label><label>Email address<input name="email" type="email" autocomplete="email" required placeholder="you@company.com"></label><label>Company / brand<input name="company" autocomplete="organization" placeholder="Your brand"></label><label>I’m looking for<select name="service" required><option value="">Choose a service</option>${[...proData().services.map(s=>s.title),'Portfolio review','Something else'].map(s=>`<option>${esc(s)}</option>`).join('')}</select></label><label>Budget range<select name="budget"><option>Let’s discuss</option>Under $1,000</option>$1,000–$3,000</option>$3,000–$5,000</option>$5,000+</option></select></label><label>Ideal start<input name="start" type="date"></label><label class="pro-wide">A little about the project<textarea name="message" required placeholder="What are you creating, and what would success look like?" rows="4"></textarea></label></div><div class="pro-form-submit"><button class="pro-primary" type="submit">Save my project brief <span>↗</span></button><button type="button" class="pro-link" data-pro-control="download">Download brief ↓</button></div><p class="pro-form-note">${esc(proData().formNote)}</p><p class="pro-form-result" role="status" aria-live="polite"></p></form>`}
const proOldContact=storyContact;
const originalProBriefForm=proBriefForm;
proBriefForm=function(){return originalProBriefForm().replace('Under $1,000</option>$1,000–$3,000</option>$3,000–$5,000</option>$5,000+</option>','<option>Under $1,000</option><option>$1,000–$3,000</option><option>$3,000–$5,000</option><option>$5,000+</option>')};
storyContact=function(s,edit){if(!state.portfolioPro)return proOldContact(s,edit);return `<section class="story-contact pro-contact" ${storyAttr(s,edit,'contact')}>${proLabel('08','YOUR NEXT CHAPTER')}<div class="pro-contact-heading" ${proEdit('contact')}><p>${esc(state.personalBrand.contactIntro||'Have an idea, a brief, or a good question?')}</p><h2>${state.personalBrand.contactTitle?directLines(state.personalBrand.contactTitle):'Let’s make<br><i>something matter.</i>'}</h2></div><div class="pro-contact-grid"><div class="pro-contact-aside"><span class="pro-availability"><b></b>Open to a conversation</span><p>Based in ${esc(state.profile.location)}.<br>Collaborating wherever good ideas happen.</p>${state.profile.email?`<a class="pro-link" href="mailto:${esc(state.profile.email)}">${esc(state.profile.email)} ↗</a>`:''}<div class="pro-socials">${socialLinks()}</div><p class="pro-form-note">For a live conversation, message me on Behance.</p></div>${proBriefForm()}</div><div class="contact-bottom"><span>YOUR VISION. OUR NEXT CONVERSATION.</span><button data-action="journey:home">Back to the top ↑</button></div></section>`};
const proOldSection=portfolioSection;
const proServicesBase=proServices;
proServices=function(s,edit){const industries=[...new Set(proProjects().map(p=>p.industry).filter(Boolean))];return proServicesBase(s,edit).replace('</div></section>',`</div><div class="pro-industries"><span class="micro-label">DIFFERENT INDUSTRIES. THE SAME CARE.</span><div>${industries.map(name=>`<span>${esc(name)}</span>`).join('')}</div></div></section>`)};
portfolioSection=function(s,edit){if(state.portfolioPro){if(s.id==='pro-services')return proServices(s,edit);if(s.id==='pro-journey')return proJourney(s);if(s.id==='pro-testimonials')return proTestimonials()+proInsights()+proMentoring()}return proOldSection(s,edit)};
const proOldWork=storyWork;
storyWork=function(s,edit){if(!state.portfolioPro)return proOldWork(s,edit);const all=proProjects(),projects=all.filter(p=>proFilter==='All'||(p.category||p.type)===proFilter);return `<section class="story-work pro-work" ${storyAttr(s,edit,'work')}>${proLabel('03','SELECTED WORK')}<div class="pro-heading pro-reveal"><h2>${state.personalBrand.workTitle?directLines(state.personalBrand.workTitle):'Different worlds.<br><i>One point of view.</i>'}</h2><p>A selection of identity, art direction and campaign work.<br>Explore a project to see the thinking behind the visuals.</p></div><div class="pro-work-tools"><div class="pro-filters" aria-label="Filter selected work">${['All',...new Set(all.map(p=>p.category||p.type))].map(c=>`<button data-pro-control="filter" data-filter="${esc(c)}" aria-pressed="${proFilter===c}">${esc(c)}</button>`).join('')}</div><span class="micro-label">${String(projects.length).padStart(2,'0')} PROJECTS</span></div><div class="story-projects" style="--story-columns:${state.personalBrand.workColumns==='3'?3:2}">${proCards(projects)}</div><a class="pro-link pro-more-work" href="${mikhaWorkSources.behance}" target="_blank" rel="noopener noreferrer">More work on Behance <span>↗</span></a></section>`};
const proOldReach=storyReach;
storyReach=function(s,edit){let html=proOldReach(s,edit);if(state.portfolioPro)html=html.replace('02 — CONNECTIONS, WITHOUT BORDERS','04 — CONNECTIONS, WITHOUT BORDERS').replace('Clients & collaborators','Brands in this selection').replace('Projects brought to life','Selected project stories').replace('Years of independent thinking','Years of design experience').replace('And counting.','Selected work.');return html};
function proSubNav(){return `<nav class="story-nav pro-subnav"><button data-action="pro-home" class="story-monogram">${esc(state.profile.name)}</button><button data-action="pro-home">Back to portfolio ←</button>${proButton('Start a project','pro-brief:')}</nav>`}
function proServicePage(id){const s=proData().services.find(s=>s.id===id)||proData().services[0],i=proData().services.indexOf(s),projects=proProjects().filter(p=>p.category===s.category);return `<article class="portfolio brand-experience pro-detail ${device}" data-motion="${state.personalBrand.motion}">${proSubNav()}<section class="pro-detail-intro pro-section" ${proEdit('services',i)}><span class="micro-label">WHAT WE CAN CREATE</span><h1>${esc(s.title)}<i>with a point of view.</i></h1><p>${esc(s.description)}</p></section><img class="pro-detail-image" src="${esc(s.image)}" alt="${esc(s.title)}"><section class="pro-section pro-deliverables"><h2>Built around<br><i>your next chapter.</i></h2><div><p>${esc(s.line)}</p><ul>${s.deliverables.split('\n').map(t=>`<li>${esc(t)}</li>`).join('')}</ul>${proButton('Discuss '+s.title.toLowerCase(),'pro-brief:'+s.title)}</div></section><section class="pro-section"><div class="pro-heading"><h2>Selected <i>work.</i></h2></div><div class="story-projects">${proCards(projects)}</div></section><section class="pro-section pro-process"><span class="micro-label">HOW WE GET THERE</span><div>${[['01','Discover','Understand the brand, audience and ambition.'],['02','Define','Agree the creative direction and visual language.'],['03','Develop','Build, refine and bring the idea into its applications.'],['04','Deliver','Prepare a coherent set of usable final assets.']].map(([n,t,p])=>`<div><span>${n}</span><h3>${t}</h3><p>${p}</p></div>`).join('')}</div></section><footer class="pro-section">${proButton('Let’s talk about your project','pro-brief:'+s.title)}</footer></article>`}
function proArticlePage(index){const a=proData().insights[index]||proData().insights[0];return `<article class="portfolio brand-experience pro-detail ${device}" data-motion="${state.personalBrand.motion}">${proSubNav()}<section class="pro-section pro-article" ${proEdit('insights',index)}><span class="micro-label">${esc(a.category)} · SAMPLE EDITORIAL DRAFT</span><h1>${esc(a.title)}</h1><img src="${esc(a.image)}" alt="Selected work illustrating the note">${a.body.split('\n\n').map(p=>`<p>${esc(p)}</p>`).join('')}</section><footer class="pro-section">${proButton('Back to the studio notes','pro-home:insights')}</footer></article>`}
const proOldPortfolio=portfolio;
portfolio=function(edit=false,mini=false){if(state.portfolioPro&&proView&&view==='preview'&&!activePreviewProject)return proView.kind==='service'?proServicePage(proView.id):proArticlePage(Number(proView.id));let html=proOldPortfolio(edit,mini);if(!state.portfolioPro||!state.personalBrand.enabled||page!=='Home')return html;return html.replace('01 — A LITTLE ABOUT ME','01 — THE PERSON BEHIND THE WORK').replace('<button data-action="journey:work">Work</button>','<button data-action="journey:services">Services</button><button data-action="journey:work">Work</button>').replace('Contact <span>↗</span>','Start a project <span>↗</span>').replace('SELECTED CLIENTS & COLLABORATORS','BRANDS IN THE SELECTED WORK · INCLUDING AGENCY COLLABORATIONS')};
const proOldCase=casePreview;
casePreview=function(){const p=state.projects.find(p=>p.id===activePreviewProject)||getProject();if(!p.category)return proOldCase();const related=proProjects().filter(q=>q.id!==p.id).sort((a,b)=>Number(b.category===p.category)-Number(a.category===p.category)).slice(0,2);return `<article class="portfolio case-preview pro-case ${device}" data-motion="${state.personalBrand.motion}"><nav class="pf-nav"><button class="pf-name" data-action="pro-home">${esc(state.profile.name)}</button><button class="pro-link" data-action="preview-home">All work ←</button>${proButton('Start a project','pro-brief:'+p.category)}</nav><header class="case-heading"><span class="micro-label">${esc(p.category)} · ${esc(p.year)} ${p.tag?'· '+esc(p.tag):''}</span><h1>${esc(p.title)}</h1><p>${esc(p.notes)}</p><div class="pro-case-meta"><div><small>CLIENT / BRAND</small><span>${esc(p.client)}</span></div><div><small>DISCIPLINE</small><span>${esc(p.role)}</span></div><div><small>SECTOR</small><span>${esc(p.industry)}</span></div></div></header><div class="project-cover pro-case-cover"><img src="${esc(p.cover)}" alt="${esc(p.title)}"></div><div class="pro-case-body">${p.blocks.filter(b=>b.visible).map(b=>`<section class="case-block ${b.type==='Big Image'?'pro-case-art':'pro-case-text'}" data-pro-block="${b.id}" data-pro-project-id="${p.id}">${renderBlock(b,p)}</section>`).join('')}</div>${p.source?`<a class="pro-source-link" href="${esc(p.source)}" target="_blank" rel="noopener noreferrer">View the complete project & credits on Behance ↗</a>`:''}<section class="pro-case-cta"><span class="micro-label">YOUR NEXT CHAPTER</span><h2>Have something<br><i>in mind?</i></h2>${proButton('Start a project together','pro-brief:'+p.category)}</section><section class="pro-section"><div class="pro-heading"><h2>Keep <i>exploring.</i></h2></div><div class="story-projects">${proCards(related)}</div></section><footer class="pf-footer"><span>© ${new Date().getFullYear()} ${esc(state.profile.name)}</span><a href="${mikhaWorkSources.behance}" target="_blank" rel="noopener noreferrer">Behance ↗</a></footer></article>`};

// New content uses the same in-page inspector and undo stack as the original canvas.
const proOldAnnotate=directAnnotate;
directAnnotate=function(){proOldAnnotate();if(!directEnabled())return;const root=document.querySelector(view==='editor'?'.canvas-wrap .portfolio':'.preview-canvas .portfolio');if(!root)return;root.classList.add('direct-canvas');root.querySelectorAll('[data-pro-edit]').forEach(el=>{el.dataset.directKey=el.dataset.proEdit==='contact'?'contact':'business';el.dataset.directId=el.dataset.proEdit;el.dataset.directBlock=el.dataset.proIndex||'0';el.tabIndex=0;el.title='Edit '+el.dataset.proEdit});root.querySelectorAll('[data-pro-project]').forEach(el=>{el.dataset.directKey='project';el.dataset.directId=el.dataset.proProject});root.querySelectorAll('[data-pro-block]').forEach(el=>{el.dataset.directKey='block';el.dataset.directId=el.dataset.proProjectId;el.dataset.directBlock=el.dataset.proBlock});};
const proOldPanel=directPanel;
directPanel=function(){if(directSelection?.key!=='business')return proOldPanel();const key=directSelection.id,index=Number(directSelection.block)||0,item=key==='mentoring'?proData().mentoring:proData()[key]?.[index];if(!item)return '';const sets={services:['title','line','description','deliverables'],testimonials:['name','role','quote'],journey:['title','company','location','detail'],insights:['title','category','body'],mentoring:['title','description','duration']};return `<aside class="right-panel direct-panel" aria-label="Selected element properties"><div class="prop-head"><div><span class="eyebrow">EDITING IN PLACE</span><h3>${esc({services:'Service',testimonials:'Sample testimonial',journey:'Experience',insights:'Studio note',mentoring:'Portfolio review'}[key])}</h3></div><button class="iconbtn" data-direct-close aria-label="Close properties">${icon('close')}</button></div><div class="direct-panel-body">${['testimonials','insights','mentoring'].includes(key)?'<p class="help-tip">Sample content for the preview. Replace it with your own approved content before publishing.</p>':''}${sets[key].map(fieldName=>directField(fieldName[0].toUpperCase()+fieldName.slice(1),'pro.'+key+'.'+index+'.'+fieldName,item[fieldName],['description','detail','quote','body','deliverables'].includes(fieldName)?'textarea':'text')).join('')}${key==='services'?proButton('View service page','pro-service:'+item.id):''}<p class="direct-saved">Saved locally as you type</p><div class="row">${ib('undo','undo','Undo change',history.length?'':'disabled')}${ib('redo','redo','Redo change',future.length?'':'disabled')}</div></div></aside>`};
const proOldChange=changeDirectField;
changeDirectField=function(id,value){if(!id.startsWith('pro.'))return proOldChange(id,value);const [,key,index,fieldName]=id.split('.');const group=directLastField===id&&Date.now()-directLastTime<1200;mutate(()=>{const item=key==='mentoring'?proData().mentoring:proData()[key][Number(index)];item[fieldName]=value},false);if(group&&history.length>1)history.pop();directLastField=id;directLastTime=Date.now();refreshDirectCanvas()};
const proOldRefresh=refreshDirectCanvas;
refreshDirectCanvas=function(){proOldRefresh();initProMotion();restoreProBrief()};
const proTextPanel=directPanel;
directPanel=function(){let html=proTextPanel();if(directSelection?.key==='business'&&['services','insights'].includes(directSelection.id)){const key=directSelection.id,index=Number(directSelection.block)||0,item=proData()[key][index];html=html.replace('<p class="direct-saved">',directMedia('proimage:'+key+':'+index,item.image,item.title)+'<p class="direct-saved">')}if(directSelection?.key==='project'){const p=state.projects.find(p=>p.id===directSelection.id);if(p?.category)html=html.replace('<p class="direct-saved">',directSelect('Project category','directproject.'+p.id+'.category',p.category,['Brand identity','Art direction','Social campaigns'])+['client','role','industry','notes'].map(k=>directField(k[0].toUpperCase()+k.slice(1),'directproject.'+p.id+'.'+k,p[k]||'',k==='notes'?'textarea':'text')).join('')+'<p class="direct-saved">')}return html};
const proApplyMedia=applyDirectMedia;
applyDirectMedia=function(target,url,name){if(!target.startsWith('proimage:'))return proApplyMedia(target,url,name);const [,key,index]=target.split(':');mutate(()=>proData()[key][Number(index)].image=url,false);refreshDirectCanvas();mountDirectPanel()};
const proContentAnnotate=directAnnotate;
directAnnotate=function(){proContentAnnotate();if(!directEnabled())return;document.querySelectorAll('.direct-canvas .pro-work .pro-heading').forEach(el=>{el.dataset.directKey='work';el.tabIndex=0;el.title='Edit project grid'})};
const proOldAction=handleExtraAction;
handleExtraAction=function(action,value){
  if(action==='pro-service'||action==='pro-article'){proView={kind:action==='pro-service'?'service':'article',id:value};activePreviewProject=null;directSelection=null;page='Home';go('preview');return}
  if(action==='pro-home'||action==='pro-brief'){proView=null;activePreviewProject=null;directSelection=null;page='Home';go('preview');requestAnimationFrame(()=>{const chapter=action==='pro-brief'?'contact':value||'home';document.querySelector('[data-chapter="'+chapter+'"]')?.scrollIntoView({behavior:'smooth',block:'start'});if(action==='pro-brief'&&value){const sel=document.querySelector('.pro-brief [name=service]');if(sel&&[...sel.options].some(o=>o.value===value)){sel.value=value;persistProBrief(sel.form)}}});return}
  if(['preview-project','preview-home'].includes(action))proView=null;
  proOldAction(action,value);
};
document.addEventListener('click',e=>{const navigation=e.target.closest('[data-action]');if(navigation&&/^(go:|page:)/.test(navigation.dataset.action))proView=null;const button=e.target.closest('[data-pro-control]');if(!button||button.tagName==='FORM')return;const action=button.dataset.proControl;if(action==='filter'){const y=button.closest('.story-work').getBoundingClientRect().top;proFilter=button.dataset.filter;refreshDirectCanvas();window.scrollBy(0,document.querySelector('.story-work').getBoundingClientRect().top-y);return}if(['slide','previous','next'].includes(action)){setProSlide(action==='slide'?Number(button.dataset.index):proSlide+(action==='next'?1:-1));return}if(action==='play'){const pressed=button.getAttribute('aria-pressed')!=='true';button.setAttribute('aria-pressed',String(pressed));button.textContent=pressed?'Pause':'Play';return}if(action==='download'){const form=button.closest('form');if(!form.reportValidity())return;const values=Object.fromEntries(new FormData(form));const body='PROJECT BRIEF — '+state.profile.name+'\n\n'+Object.entries(values).map(([k,v])=>k.toUpperCase()+': '+v).join('\n\n')+'\n\nPrepared locally. Not sent.';const url=URL.createObjectURL(new Blob([body],{type:'text/plain'}));const a=document.createElement('a');a.href=url;a.download='project-brief.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}},true);
function setProSlide(index){const n=proData().testimonials.length;proSlide=(index+n)%n;document.querySelectorAll('[data-pro-slide]').forEach((el,i)=>{el.hidden=i!==proSlide;el.classList.toggle('is-active',i===proSlide)});document.querySelectorAll('[data-pro-control=slide]').forEach((el,i)=>el.setAttribute('aria-pressed',String(i===proSlide)));const count=document.querySelector('.pro-slide-count');if(count)count.textContent=String(proSlide+1).padStart(2,'0')+' / '+String(n).padStart(2,'0')}
function persistProBrief(form){try{sessionStorage.setItem('sitofolio-project-brief',JSON.stringify(Object.fromEntries(new FormData(form))))}catch{}}
function restoreProBrief(){const form=document.querySelector('.pro-brief');if(!form)return;try{const draft=JSON.parse(sessionStorage.getItem('sitofolio-project-brief')||'{}');for(const [key,value] of Object.entries(draft)){const input=form.elements.namedItem(key);if(input)input.value=value}}catch{}}
document.addEventListener('input',e=>{const form=e.target.closest('.pro-brief');if(form)persistProBrief(form)});
document.addEventListener('change',e=>{const form=e.target.closest('.pro-brief');if(form)persistProBrief(form)});
document.addEventListener('submit',e=>{if(!e.target.matches('.pro-brief'))return;e.preventDefault();persistProBrief(e.target);e.target.querySelector('.pro-form-result').textContent='Brief saved in this tab. Nothing has been sent. Download a copy or message me on Behance.'});
function initProMotion(){stopProMotion();const cleanups=[];const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches||state.personalBrand.motion==='Off';if(!reduce){const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('pro-visible');observer.unobserve(entry.target)}}),{threshold:.07});document.querySelectorAll('.pro-reveal').forEach(el=>{el.classList.add('pro-will-reveal');observer.observe(el)});cleanups.push(()=>observer.disconnect())}else document.querySelectorAll('.pro-reveal').forEach(el=>el.classList.remove('pro-will-reveal'));const slider=document.querySelector('.pro-testimonials');if(slider&&!reduce){let visible=false;const io=new IntersectionObserver(entries=>visible=entries[0].isIntersecting);io.observe(slider);const timer=setInterval(()=>{if(visible&&!document.hidden&&!slider.matches(':hover,:focus-within')&&slider.querySelector('[data-pro-control=play]')?.getAttribute('aria-pressed')==='true')setProSlide(proSlide+1)},6500);cleanups.push(()=>{io.disconnect();clearInterval(timer)})}stopProMotion=()=>cleanups.forEach(fn=>fn())}
const proOldRender=render;
render=function(){stopProMotion();proOldRender();if(view==='preview'&&state.portfolioPro&&document.querySelector('.pro-case,.pro-detail'))document.body.classList.add('immersive-preview');restoreProBrief();requestAnimationFrame(initProMotion)};
matchMedia('(prefers-reduced-motion: reduce)').addEventListener('change',initProMotion);
render();
